SELECT ps.* FROM playlist_song ps JOIN song s ON s.id = ps.song_id WHERE ps.playlist_id = #{playlistId} AND ps.deleted = 0 AND s.status = 1 AND s.deleted = 0
AND ( s.uploader_id IS NULL
OR s.uploader_id IN
#{uploaderId}
)
AND (s.name LIKE CONCAT('%', #{keyword}, '%') OR s.artist_names LIKE CONCAT('%', #{keyword}, '%'))
AND s.language = #{language}
ORDER BY s.name ASC, ps.id ASC ORDER BY s.artist_names ASC, s.name ASC, ps.id ASC ORDER BY s.duration ASC, ps.id ASC ORDER BY ps.sort_order ASC, ps.id ASC

SELECT COUNT(*) FROM playlist_song ps JOIN song s ON s.id = ps.song_id WHERE ps.playlist_id = #{playlistId} AND ps.deleted = 0 AND s.status = 1 AND s.deleted = 0
AND ( s.uploader_id IS NULL
OR s.uploader_id IN
#{uploaderId}
)
